const clamp=(v)=>Math.max(0,Math.min(1,v)),smooth=(a,b,v)=>{const t=clamp((v-a)/(b-a));return t*t*(3-2*t);};
const keys=[{h:0,sky:[.07,.11,.2],fog:[.09,.13,.19],amb:[.055,.07,.11],ground:[.11,.14,.17],sun:[.14,.17,.25]},{h:5,sky:[.25,.28,.4],fog:[.31,.28,.27],amb:[.16,.13,.13],ground:[.23,.24,.19],sun:[.72,.43,.3]},{h:7,sky:[.56,.67,.76],fog:[.62,.69,.65],amb:[.32,.33,.28],ground:[.34,.4,.25],sun:[1,.72,.48]},{h:12,sky:[.72,.85,.94],fog:[.76,.85,.83],amb:[.42,.44,.37],ground:[.45,.54,.34],sun:[1,.96,.82]},{h:17,sky:[.88,.6,.42],fog:[.71,.56,.49],amb:[.38,.29,.23],ground:[.32,.36,.24],sun:[1,.57,.34]},{h:19,sky:[.25,.26,.39],fog:[.3,.29,.36],amb:[.13,.13,.19],ground:[.16,.19,.19],sun:[.48,.33,.4]},{h:21,sky:[.07,.11,.2],fog:[.09,.13,.19],amb:[.055,.07,.11],ground:[.11,.14,.17],sun:[.14,.17,.25]},{h:24,sky:[.07,.11,.2],fog:[.09,.13,.19],amb:[.055,.07,.11],ground:[.11,.14,.17],sun:[.14,.17,.25]}];
function color(hour,key){let i=0;while(i<keys.length-2&&hour>keys[i+1].h)i++;const a=keys[i],b=keys[i+1],t=clamp((hour-a.h)/(b.h-a.h));return a[key].map((v,j)=>v+(b[key][j]-v)*t);}
export function sampleDayCycle(seconds,{period=720,startHour=8}={}){const hour=((startHour+Math.max(0,seconds)/period*24)%24+24)%24,elevation=Math.sin((hour-6)/12*Math.PI),daylight=smooth(-.45,.24,elevation),label=hour<5||hour>=21?'ليل هادئ':hour<7?'الفجر':hour<12?'الصباح':hour<16?'الظهيرة':hour<19?'العصر':'الغروب',angle=(hour-6)/12*Math.PI,dx=-Math.cos(angle),dy=-Math.max(.12,elevation*1.65),dz=Math.sin(angle)*.48,len=Math.hypot(dx,dy,dz)||1;return {hour,daylight,label,sunIntensity:.075+daylight*1.05,hemiIntensity:.2+daylight*.5,exposure:.88+daylight*.17,sky:color(hour,'sky'),fog:color(hour,'fog'),ambient:color(hour,'amb'),ground:color(hour,'ground'),sun:color(hour,'sun'),sunDirection:[dx/len,dy/len,dz/len]};}
export function createDayCycle(B,scene,world,{period=720,startHour=8}={}){let elapsed=0,current=sampleDayCycle(0,{period,startHour});function apply(s){scene.clearColor.r=s.sky[0];scene.clearColor.g=s.sky[1];scene.clearColor.b=s.sky[2];scene.fogColor.set(...s.fog);scene.ambientColor.set(...s.ambient);scene.imageProcessingConfiguration.exposure=s.exposure;world.sun.diffuse.set(...s.sun);world.sun.intensity=s.sunIntensity;world.sun.direction.set(...s.sunDirection);world.sun.position.set(-s.sunDirection[0]*55,-s.sunDirection[1]*55,-s.sunDirection[2]*55);world.hemi.intensity=s.hemiIntensity;world.hemi.groundColor.set(...s.ground);}apply(current);function snapshot(){return {...current,elapsed,period,startHour};}function advance(seconds){elapsed=Math.max(0,elapsed+seconds);current=sampleDayCycle(elapsed,{period,startHour});apply(current);return snapshot();}function update(dt){if(dt>0&&Number.isFinite(dt)){elapsed+=Math.min(dt,.2);current=sampleDayCycle(elapsed,{period,startHour});apply(current);}return snapshot();}return {update,advance,snapshot};}
